/* Dangerous Walrus 7 by SouravBandyopadhyay — https://uiverse.io/SouravBandyopadhyay/dangerous-walrus-7 */
.container {
  width: 100%;
  height: 100%;
  background: linear-gradient(
      45deg,
      transparent 33.33%,
      rgba(57, 144, 179, 0.1) 33.33%,
      rgba(0, 0, 0, 0.1) 66.66%,
      transparent 66.66%
    ),
    lightblue;
  background-size: 20px 20px;
}
